/* Avoid input focus border */
:focus {
	outline: none;
}
::-moz-focus-inner {
	border: 0;
}

* {
	-moz-user-select: none;
}

html,
body {
	touch-action: manipulation;
	margin: 0;
}

/* Prevent mobile browser auto-zoom on input focus and double-tap */
:host {
	touch-action: manipulation;
}

input,
textarea,
select {
	touch-action: manipulation;
}

canvas {
	touch-action: none;
}

body {
	background-color: black;
	font-size: 12px;
	/* 'SCDream' first: wins only when the server actually serves the client font (loaded via
	   @font-face in DBManager). When it isn't served it resolves to Arial — the official client's
	   window UI font for intl/america servicetype (Ragexe draws window text with CreateFontA on the
	   Gulim/Arial face table). Liberation Sans / Arimo provide Arial metrics on Linux. */
	font-family: 'SCDream', Arial, 'Liberation Sans', Arimo, sans-serif;
	/* Normalize any resolved font's x-height to Arial's (sxHeight 1062 / unitsPerEm 2048 = 0.5186),
	   so text keeps Arial's apparent size on every OS/font. It's inherited and crosses Shadow DOM
	   hosts, so it also rescales elements that use a non-Arial face; those opt out with
	   `font-size-adjust: none` on the selector declaring that font (Intro, GrfViewer, JoystickUI
	   header). SCDream, when a server serves it, is normalized to Arial on purpose.
	   Progressive enhancement: engines that don't support the numeric form ignore it
	   and render at the resolved font's native x-height (no JS fallback needed — Arial
	   / Liberation Sans already carry correct metrics, only annex fonts degrade). */
	font-size-adjust: 0.5186;
	overflow: hidden;
	-webkit-user-select: none;
	user-select: none;
	min-width: 100vw;
	min-height: 100vh;
	letter-spacing: 0;
	line-height: 1.2;
}

.title {
	font-size: 12px;
}

button,
ui-button {
	padding: 0;
}

ui-button {
	display: inline-block;
}

/* Text over a bitmap skin: keep typography centered without changing the skin. */
.ui-button-text {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	box-sizing: border-box;
	padding: 0;
	font-family: inherit;
	font-size: 12px;
	line-height: 1;
	text-align: center;
	white-space: nowrap;
}

.ui-btn {
	-webkit-appearance: none;
	appearance: none;
	display: inline-flex;
	align-items: center;
	justify-content: center;

	height: 20px;
	min-width: 52px;
	padding: 0 10px;

	font-size: 12px;
	line-height: 1;
	color: #3f3f3f;
	text-shadow: 1px 1px 0 rgba(255, 255, 255, 0.85);

	border-radius: 4px;
	border: 1px solid;

	/* 3D border: top right bottom left */
	border-color: #cfcfcf #a9a9a9 #5f5f5f #bdbdbd;

	/* glossy + subtle depth */
	background: linear-gradient(to bottom, #ffffff 0%, #f2f2f2 35%, #dcdcdc 55%, #f9f9f9 100%);

	box-shadow:
		inset 0 1px 0 rgba(255, 255, 255, 0.95),
		/* top highlight */ inset 0 -1px 0 rgba(0, 0, 0, 0.12),
		/* bottom inner edge */ 0 1px 0 rgba(0, 0, 0, 0.12); /* outer bottom shadow */

	cursor: pointer;
}

/* Hover: hơi xanh nhẹ giống button Reset */
.ui-btn:hover {
	border-color: #c9d1dd #8ea2c4 #4d5f86 #b1bfd5;
	background: linear-gradient(to bottom, #f7fbff 0%, #dfe8f6 35%, #c0d0ee 55%, #f0f6ff 100%);

	box-shadow:
		inset 0 1px 0 rgba(255, 255, 255, 0.95),
		inset 0 -1px 0 rgba(0, 0, 0, 0.12),
		0 1px 0 rgba(0, 0, 0, 0.12);
}

/* Active: giống "ấn xuống" */
.ui-btn:active {
	border-color: #9fb0c9 #6f86a6 #3b4b67 #7f96b6;

	background: linear-gradient(to bottom, #cdd8eb 0%, #b7c8e5 45%, #dfe9fb 100%);

	box-shadow:
		inset 0 2px 3px rgba(0, 0, 0, 0.18),
		inset 0 1px 0 rgba(255, 255, 255, 0.35);

	transform: translateY(1px); /* cảm giác bị nhấn */
}

/* Disabled */
.ui-btn:disabled,
.ui-btn.is-disabled {
	cursor: default;
	color: #8f8f8f;
	text-shadow: none;

	border-color: #d3d3d3 #bdbdbd #9b9b9b #c9c9c9;

	background: linear-gradient(to bottom, #f6f6f6 0%, #e7e7e7 55%, #fafafa 100%);

	box-shadow:
		inset 0 1px 0 rgba(255, 255, 255, 0.9),
		inset 0 -1px 0 rgba(0, 0, 0, 0.08),
		0 1px 0 rgba(0, 0, 0, 0.08);

	transform: none;
}

.ui-btn.localized-control {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	box-sizing: border-box;
	width: auto;
	min-width: 42px;
	height: 20px;
	padding: 0 8px;
	font-size: 12px;
	line-height: 1;
	border: 1px solid #8b9690 !important;
	background: #f4f7f5 !important;
	color: #202622;
}

.ui-btn.localized-control:hover {
	background: #dcebe3 !important;
}

.ui-btn.localized-control:active {
	background: #c8ded2 !important;
}

/* Hide native cursor inside Shadow DOM when custom cursor is active */
:host-context(.custom-cursor) * {
	cursor: none !important;
}

/* Touch-primary screens do not display a mouse cursor, including inside UI roots. */
@media (pointer: coarse) {
	*,
	:host {
		cursor: none !important;
	}
}

/* Native dialogs are above the game cursor's layer; keep their pointer visible. */
@media (pointer: fine) {
	:host-context(.custom-cursor) dialog:modal,
	:host-context(.custom-cursor) dialog:modal * {
		cursor: auto !important;
	}
	:host-context(.custom-cursor) dialog:modal :is(button, [role='button']) {
		cursor: pointer !important;
	}
	:host-context(.custom-cursor) dialog:modal :is(input, textarea) {
		cursor: text !important;
	}
}
:host {
	top: 100px;
	left: 100px;
	width: 288px;
	height: 114px;
}

#vendingshop {
	position: absolute;
	width: 288px;
	height: 114px;
}
#vendingshop table {
	border-spacing: 0px;
	display: inline-block;
}

#vendingshop .titlebar {
	width: 100%;
	height: 17px;
	background-color: white;
	background-repeat: repeat-x;
	border-radius: 3px 3px 0px 0px;
}
#vendingshop .titlebar .base {
	width: 11px;
	height: 11px;
	border: none;
	background-color: transparent;
	background-repeat: no-repeat;
	vertical-align: middle;
}
#vendingshop .titlebar .text {
	text-shadow: 1px 1px white;
	vertical-align: -2px;
	white-space: nowrap;
	/* chrome bug */
	display: inline-block;
	width: 32px;
	height: 13px;
	font-size: 11px;
	font-weight: bold;
}
#vendingshop .titlebar .left {
	margin-left: 3px;
	float: left;
}
#vendingshop .titlebar .clear {
	clear: both;
}

#vendingshop .container {
	padding-left: 16px;
	border-right: 1px solid #ccc;
	background: white;
}
#vendingshop .ff_bugfix {
	position: relative;
	width: 100%;
	height: 100%;
}
#vendingshop .hide {
	height: 100%;
	width: 16px;
	position: absolute;
	top: 0px;
	right: 0px;
	background-color: white;
}
#vendingshop .content {
	overflow: auto;
	width: 100%;
	height: 100%;
	min-height: 65px;
	background-color: transparent;
	background-repeat: repeat;
}

#vendingshop .content .item {
	display: block;
	width: 24px;
	height: 24px;
	margin: 4px 4px 4px 4px;
	position: relative;
	float: left;
}
#vendingshop .content .item .icon {
	width: 24px;
	height: 24px;
	border: none;
	background-color: transparent;
	background-repeat: no-repeat;
}
#vendingshop .overlay {
	position: absolute;
	display: none;
	white-space: nowrap;
	z-index: 900;
	height: 13px;
	padding: 5px;
	background: rgba(0, 0, 0, 0.7);
	color: white;
	text-shadow: 1px 1px black;
}
#vendingshop .overlay.grey {
	color: #aaa;
}
#vendingshop .content .item .amount {
	position: relative;
	bottom: 9px;
	right: 0px;
	text-align: right;
	text-shadow: -1px -1px white;
}

#vendingshop .footer {
	width: 100%;
	height: 27px;
	background-repeat: repeat-x;
	background-color: transparent;
	position: relative;
	border-right: 1px solid #ccc;
}
#vendingshop .footer .right {
	float: right;
	margin-right: 3px;
}
#vendingshop .btn {
	width: 42px;
	height: 20px;
	border: none;
	margin: 0;
	background-color: transparent;
	background-repeat: no-repeat;
}



